/** Reduced real-transfer regression controls, independent of Mekanism/JDT world fixtures. */
@SFMGameTest
public class ReleaseEnergyExtractionProgressGameTest extends SFMGameTestDefinition {
    @Override public String template() { return "3x2x1"; }
    @Override public String testName() { return "release_energy_extraction_progress"; }

    @Override
    public void run(SFMGameTestHelper helper) {
        var position = new BlockPos(1, 2, 0);
        helper.setBlock(position, SFMBlocks.MANAGER.get());
        var manager = helper.getBlockEntity(position, ManagerBlockEntity.class);
        manager.setItem(0, new ItemStack(SFMItems.DISK.get()));
        manager.setProgram("EVERY 20 TICKS DO\nEND");
        helper.assertManagerRunning(manager);
        var context = new ProgramContext(
                Objects.requireNonNull(manager.getProgram()), manager, new ExecuteProgramBehaviour()
        );

        refusedOneThenProgress(helper, context);
        partialTwentyFiveThenProgress(helper, context);
        unrestrictedControl(helper, context);
        limitedProgress(helper, context, 20, 0, 20, "Input quantity");
        limitedProgress(helper, context, Long.MAX_VALUE, 80, 20, "Input retention");
        limitedProgress(helper, context, 20, 60, 20, "Quantity before retention");
        limitedProgress(helper, context, 40, 80, 20, "Retention before quantity");
        outputQuantityControl(helper, context);
        resourceFilterControl(helper, context);
        boundedRefusalAndEmptyControl(helper, context);
        helper.succeed();
    }

    private static void refusedOneThenProgress(SFMGameTestHelper helper, ProgramContext context) {
        var type = SFMResourceTypes.FORGE_ENERGY.get();
        var source = storage(100, 2);
        var small = storage(999, 1);
        var large = storage(0, 1);
        var input = input(type, source, Limit.MAX_QUANTITY_NO_RETENTION);
        helper.assertTrue(!input.isDone() && input.tracker.matchesStack(type.getStackInSlot(source, 0)),
                "Fixture must select a nonempty Energy source");
        OutputStatement.moveTo(context, input, output(type, small));
        helper.assertTrue(stored(source) == 100 && stored(small) == 999 && !input.isDone(),
                "A refused one-FE pair must conserve Energy and keep the whole input source available");
        helper.assertTrue(input.tracker.getMaxTransferable(type, type.getStackInSlot(source, 0)) == Long.MAX_VALUE,
                "A refused one-FE request must not consume input quantity");
        OutputStatement.moveTo(context, input, output(type, large));
        helper.assertTrue(stored(source) == 0 && stored(small) == 999 && stored(large) == 100 && input.isDone(),
                "The later destination must receive all 100 FE; only exhaustion finishes this input");
    }

    private static void partialTwentyFiveThenProgress(SFMGameTestHelper helper, ProgramContext context) {
        var type = SFMResourceTypes.FORGE_ENERGY.get();
        int[] attempts = {0};
        var source = storage(100, 2, attempts);
        var small = storage(975, 1);
        var large = storage(0, 1);
        var input = input(type, source, Limit.MAX_QUANTITY_NO_RETENTION);
        OutputStatement.moveTo(context, input, output(type, small));
        helper.assertTrue(stored(source) == 76 && stored(small) == 999 && !input.isDone(),
                "A quantized 25-FE request must move 24 FE and leave one FE of destination room");
        OutputStatement.moveTo(context, input, output(type, small));
        helper.assertTrue(stored(source) == 76 && stored(small) == 999 && !input.isDone(),
                "The remaining one-FE request must not retire a source that still contains 76 FE");
        helper.assertTrue(input.tracker.getMaxTransferable(type, type.getStackInSlot(source, 0)) == Long.MAX_VALUE - 24,
                "Only the 24 FE actually moved may consume the input quantity budget");
        OutputStatement.moveTo(context, input, output(type, large));
        helper.assertTrue(stored(source) == 0 && stored(small) == 999 && stored(large) == 76
                        && attempts[0] == 3 && input.isDone(),
                "Later progress must conserve all Energy with one extraction call per tested destination pair");
    }

    private static void unrestrictedControl(SFMGameTestHelper helper, ProgramContext context) {
        var type = SFMResourceTypes.FORGE_ENERGY.get();
        var source = storage(100, 1);
        var small = storage(999, 1);
        var large = storage(0, 1);
        var input = input(type, source, Limit.MAX_QUANTITY_NO_RETENTION);
        OutputStatement.moveTo(context, input, output(type, small));
        helper.assertTrue(stored(source) == 99 && stored(small) == 1000 && !input.isDone(),
                "An ordinary source must still satisfy a one-FE request");
        OutputStatement.moveTo(context, input, output(type, large));
        helper.assertTrue(stored(source) == 0 && stored(large) == 99 && input.isDone(),
                "Ordinary Energy transfer must conserve the remaining source");
    }

    private static void limitedProgress(SFMGameTestHelper helper, ProgramContext context,
                                        long quantity, long retention, int expected, String control) {
        var type = SFMResourceTypes.FORGE_ENERGY.get();
        var source = storage(100, 2);
        var small = storage(999, 1);
        var large = storage(0, 1);
        var finalDestination = storage(0, 1);
        var input = input(type, source, limit(quantity, retention));
        OutputStatement.moveTo(context, input, output(type, small));
        helper.assertTrue(stored(source) == 100 && stored(small) == 999 && !input.isDone()
                        && input.tracker.getMaxTransferable(type, type.getStackInSlot(source, 0)) == quantity,
                control + " must survive a failed small request without spending input quantity");
        OutputStatement.moveTo(context, input, output(type, large));
        helper.assertTrue(stored(source) == 100 - expected && stored(large) == expected
                        && input.tracker.getMaxTransferable(type, type.getStackInSlot(source, 0)) == quantity - expected,
                control + " must constrain later progress and conserve Energy");
        // Retention-only inputs finish when the next destination observes that no movable Energy remains.
        if (!input.isDone()) OutputStatement.moveTo(context, input, output(type, finalDestination));
        helper.assertTrue(stored(source) == 100 - expected && stored(large) == expected
                        && stored(finalDestination) == 0 && input.isDone(),
                control + " must also constrain every later destination");
    }

    private static void outputQuantityControl(SFMGameTestHelper helper, ProgramContext context) {
        var type = SFMResourceTypes.FORGE_ENERGY.get();
        var source = storage(100, 2);
        var first = storage(0, 1);
        var later = storage(0, 1);
        var input = input(type, source, Limit.MAX_QUANTITY_NO_RETENTION);
        var output = output(type, first, resourceIds(type), limit(20, Long.MAX_VALUE));
        OutputStatement.moveTo(context, input, output);
        helper.assertTrue(stored(source) == 80 && stored(first) == 20 && !input.isDone()
                        && output.tracker.getMaxTransferable(type, type.getStackInSlot(source, 0)) == 0,
                "Output quantity must limit its destination without finishing the input source");
        OutputStatement.moveTo(context, input, output(type, later));
        helper.assertTrue(stored(source) == 0 && stored(later) == 80 && input.isDone(),
                "A later output may receive the remaining 80 FE");
    }

    private static void resourceFilterControl(SFMGameTestHelper helper, ProgramContext context) {
        var type = SFMResourceTypes.FORGE_ENERGY.get();
        int[] attempts = {0};
        var source = storage(100, 2, attempts);
        var rejected = storage(0, 1);
        var accepted = storage(0, 1);
        var input = input(type, source, Limit.MAX_QUANTITY_NO_RETENTION);
        OutputStatement.moveTo(context, input,
                output(type, rejected, ResourceIdSet.EMPTY, Limit.MAX_QUANTITY_MAX_RETENTION));
        helper.assertTrue(stored(source) == 100 && stored(rejected) == 0 && attempts[0] == 0 && !input.isDone(),
                "A destination resource filter must reject Energy before any source extraction");
        OutputStatement.moveTo(context, input, output(type, accepted));
        helper.assertTrue(stored(source) == 0 && stored(accepted) == 100 && input.isDone(),
                "Resource rejection must leave the source available to a matching later output");
    }

    private static void boundedRefusalAndEmptyControl(SFMGameTestHelper helper, ProgramContext context) {
        var type = SFMResourceTypes.FORGE_ENERGY.get();
        int[] attempts = {0};
        var source = storage(100, 0, attempts);
        var input = input(type, source, Limit.MAX_QUANTITY_NO_RETENTION);
        for (int i = 0; i < 256; i++) {
            var destination = storage(0, 1);
            helper.assertTrue(!input.isDone(), "Nonempty refusal must leave each later destination reachable");
            OutputStatement.moveTo(context, input, output(type, destination));
            helper.assertTrue(stored(destination) == 0, "Refusal must not create destination Energy");
        }
        helper.assertTrue(attempts[0] == 256 && stored(source) == 100 && !input.isDone()
                        && input.tracker.getMaxTransferable(type, type.getStackInSlot(source, 0)) == Long.MAX_VALUE,
                "Always-refusing extraction must stay bounded by destination count and conserve source/quantity");
        int[] emptyAttempts = {0};
        var empty = storage(0, 2, emptyAttempts);
        var emptyInput = input(type, empty, Limit.MAX_QUANTITY_NO_RETENTION);
        helper.assertTrue(emptyInput.isDone() && emptyAttempts[0] == 0,
                "An initially empty source must finish before any extraction is attempted");
    }

    private static <STACK, ITEM, CAP> LimitedInputSlot<STACK, ITEM, CAP> input(
            ResourceType<STACK, ITEM, CAP> type, CAP handler, Limit limit) {
        return new LimitedInputSlot<>(new Label("source"), BlockPos.ZERO, null, 0, handler,
                new ResourceLimit(resourceIds(type), limit, With.ALWAYS_TRUE).createInputTracker(ResourceIdSet.EMPTY),
                type.getStackInSlot(handler, 0), type);
    }

    private static <STACK, ITEM, CAP> LimitedOutputSlot<STACK, ITEM, CAP> output(
            ResourceType<STACK, ITEM, CAP> type, CAP handler) {
        return output(type, handler, resourceIds(type), Limit.MAX_QUANTITY_MAX_RETENTION);
    }

    private static <STACK, ITEM, CAP> LimitedOutputSlot<STACK, ITEM, CAP> output(
            ResourceType<STACK, ITEM, CAP> type, CAP handler, ResourceIdSet ids, Limit limit) {
        return new LimitedOutputSlot<>(new Label("destination"), BlockPos.ZERO, null, 0, handler,
                new ResourceLimit(ids, limit, With.ALWAYS_TRUE).createOutputTracker(ResourceIdSet.EMPTY),
                type.getStackInSlot(handler, 0), type);
    }

    private static ResourceIdSet resourceIds(ResourceType<?, ?, ?> type) {
        var key = SFMResourceTypes.registry().getId(type);
        return new ResourceIdSet(List.of(new ResourceIdentifier<>(key.getNamespace(), key.getPath(), ".*", ".*")));
    }

    private static Limit limit(long quantity, long retention) {
        return new Limit(
                new ResourceQuantity(new ca.teamdman.sfml.ast.Number(quantity), ResourceQuantity.IdExpansionBehaviour.NO_EXPAND),
                new ResourceQuantity(new ca.teamdman.sfml.ast.Number(retention), ResourceQuantity.IdExpansionBehaviour.NO_EXPAND)
        );
    }

    private static EnergyHandler storage(int initial, int quantum) {
        return storage(initial, quantum, new int[1]);
    }

    private static EnergyHandler storage(int initial, int quantum, int[] attempts) {
        return new SimpleEnergyHandler(1000, 1000, 1000, initial) {
            @Override
            public int extract(int amount, TransactionContext transaction) {
                attempts[0]++;
                return quantum == 0 ? 0 : super.extract(amount - amount % quantum, transaction);
            }
        };
    }

    private static int stored(EnergyHandler handler) {
        return handler.getAmountAsInt();
    }
}

